// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 amt1, uint256 amt2) public {
        vm.assume(actor != address(0));
        vm.assume(amt1 > 0 && amt2 > 0);
        vm.assume(amt1 <= type(uint256).max / 2 && amt2 <= type(uint256).max / 2);

        vm.deal(actor, amt1 + amt2);

        vm.prank(actor);
        c.addToBalance{value: amt1}();
        uint256 balAfterFirst = c.getBalance(actor);

        vm.prank(actor);
        c.addToBalance{value: amt2}();
        uint256 balAfterSecond = c.getBalance(actor);

        assertTrue(balAfterSecond >= balAfterFirst);
    }
}
